import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA source implementing fp16 cross‑entropy (mean reduction)
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>
#include <vector>
#include <cmath>

__global__ void cross_entropy_kernel(const half* __restrict__ logits,
                                     const int64_t* __restrict__ targets,
                                     float* __restrict__ sum,
                                     int batch,
                                     int classes) {
    extern __shared__ float sh[];
    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;
    if (batch_idx >= batch) return;

    // ---------- max ----------
    float max_val = -3.402823466e+38F;               // -FLT_MAX
    for (int i = tid; i < classes; i += blockDim.x) {
        float v = __half2float(logits[batch_idx * classes + i]);
        max_val = fmaxf(max_val, v);
    }
    sh[tid] = max_val;
    __syncthreads();
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            sh[tid] = fmaxf(sh[tid], sh[tid + stride]);
        }
        __syncthreads();
    }
    max_val = sh[0];

    // ---------- sum of exp ----------
    float sumexp = 0.0f;
    for (int i = tid; i < classes; i += blockDim.x) {
        float v = __half2float(logits[batch_idx * classes + i]);
        sumexp += expf(v - max_val);
    }
    sh[tid] = sumexp;
    __syncthreads();
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            sh[tid] += sh[tid + stride];
        }
        __syncthreads();
    }
    sumexp = sh[0];
    float log_sumexp = logf(sumexp);

    // ---------- loss for the target ----------
    int target = static_cast<int>(targets[batch_idx]);
    float loss = 0.0f;
    for (int i = tid; i < classes; i += blockDim.x) {
        if (i == target) {
            float v = __half2float(logits[batch_idx * classes + i]);
            loss = -(v - max_val - log_sumexp);
        }
    }
    sh[tid] = loss;
    __syncthreads();
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            sh[tid] += sh[tid + stride];
        }
        __syncthreads();
    }
    if (tid == 0) {
        atomicAdd(sum, sh[0]);               // sum in FP32
    }
}

torch::Tensor cross_entropy_fp16(torch::Tensor logits, torch::Tensor targets) {
    const int batch   = logits.size(0);
    const int classes = logits.size(1);

    auto sum = torch::zeros({1},
                torch::dtype(torch::kFloat32).device(logits.device()));

    const int threads = 256;
    const int blocks  = batch;
    const size_t shmem = threads * sizeof(float);

    // launch kernel (logits are half, targets are int64)
    cross_entropy_kernel<<<blocks, threads, shmem, at::cuda::getCurrentCUDAStream()>>>(
        logits.data_ptr<at::Half>(),
        targets.data_ptr<int64_t>(),
        sum.data_ptr<float>(),
        batch,
        classes);

    cudaDeviceSynchronize();

    float loss = sum.item<float>() / static_cast<float>(batch);
    // return as half scalar to match the dtype of the input tensor
    return torch::scalar_tensor(__float2half(loss),
                torch::dtype(torch::kFloat16).device(logits.device()));
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("cross_entropy_fp16", &cross_entropy_fp16, "FP16 Cross Entropy (mean)");
}
'''

# Compile the inline extension
cross_entropy_mod = load_inline(name='cross_entropy_cuda',
                               cpp_sources='',
                               cuda_sources=cuda_source,
                               functions=['cross_entropy_fp16'],
                               verbose=False)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
    def forward(self, predictions, targets):
        return cross_entropy_mod.cross_entropy_fp16(predictions, targets)
